import React,{useCallback,useEffect,useMemo,useState} from 'react'; import {listLibrary,removeLibraryItem} from '../../../api/userDataApi'; import PosterCard from '../../../components/media/PosterCard'; import EmptyState from '../../../components/ui/EmptyState'; import ErrorState from '../../../components/ui/ErrorState'; import Skeleton from '../../../components/ui/Skeleton'; import Button from '../../../components/ui/Button'; import SectionHeader from '../../../components/ui/SectionHeader';
const LibraryPage=({kind='watchlist'})=>{const[items,setItems]=useState([]);const[loading,setLoading]=useState(true);const[error,setError]=useState(null);const[mediaType,setMediaType]=useState('all');const[sort,setSort]=useState('newest');const apiKind=kind==='favorite'?'favorites':'watchlist';const title=kind==='favorite'?'Favorites':'Watchlist';const load=useCallback(async()=>{try{setLoading(true);setError(null);const response=await listLibrary(apiKind,{mediaType:mediaType==='all'?undefined:mediaType,sort});setItems(response.data?.data?.items||[]);}catch(requestError){setError(requestError);setItems([]);}finally{setLoading(false);}},[apiKind,mediaType,sort]);useEffect(()=>{load();},[load]);const cards=useMemo(()=>items.map(item=>({id:item.tmdbId,media_type:item.mediaType,title:item.mediaType==='movie'?item.title:undefined,name:item.mediaType==='tv'?item.title:undefined,poster_path:item.posterPath,backdrop_path:item.backdropPath,release_date:item.mediaType==='movie'?item.releaseDate:undefined,first_air_date:item.mediaType==='tv'?item.releaseDate:undefined,vote_average:item.rating,_id:item._id})),[items]);const remove=async(event,item)=>{event.preventDefault();event.stopPropagation();await removeLibraryItem(apiKind,item.media_type,item.id);setItems(current=>current.filter(saved=>saved._id!==item._id));};return <section className='mx-auto w-full max-w-[1600px] px-4 py-10 sm:px-6 lg:px-10'><SectionHeader title={title} description={kind==='favorite'?'Titles you especially enjoy.':'Movies and shows you want to watch later.'}/><div className='mb-7 flex flex-wrap gap-3'><select value={mediaType} onChange={e=>setMediaType(e.target.value)} className='rounded-xl border border-white/10 bg-neutral-900 px-4 py-2 text-sm text-white'><option value='all'>All media</option><option value='movie'>Movies</option><option value='tv'>TV shows</option></select><select value={sort} onChange={e=>setSort(e.target.value)} className='rounded-xl border border-white/10 bg-neutral-900 px-4 py-2 text-sm text-white'><option value='newest'>Newest first</option><option value='oldest'>Oldest first</option><option value='rating'>Highest TMDB rating</option></select></div>{loading?<div className='grid grid-cols-2 gap-4 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6'>{Array.from({length:12}).map((_,i)=><Skeleton key={i} className='aspect-[2/3] w-full'/>)}</div>:null}{!loading&&error?<ErrorState message={`Unable to load your ${title.toLowerCase()}.`} onRetry={load}/>:null}{!loading&&!error&&!cards.length?<EmptyState title={`Your ${title.toLowerCase()} is empty`} message={kind==='favorite'?'Favorite a movie or TV show from its details page.':'Save a movie or TV show from its details page to watch later.'}/>:null}{!loading&&!error&&cards.length?<div className='grid grid-cols-2 gap-5 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6'>{cards.map(item=><div key={item._id} className='min-w-0'><PosterCard data={item} media_type={item.media_type}/><Button variant='ghost' className='mt-2 w-full text-xs' onClick={event=>remove(event,item)}>Remove</Button></div>)}</div>:null}</section>;}; export default LibraryPage;
