import appApiClient from './appApiClient';
export const listLibrary=(kind,params={})=>appApiClient.get(`/${kind}`,{params}); export const addLibraryItem=(kind,payload)=>appApiClient.post(`/${kind}`,payload); export const removeLibraryItem=(kind,mediaType,tmdbId)=>appApiClient.delete(`/${kind}/${mediaType}/${tmdbId}`); export const checkLibraryItem=(kind,mediaType,tmdbId)=>appApiClient.get(`/${kind}/check/${mediaType}/${tmdbId}`);
export const getMyRating=(mediaType,tmdbId)=>appApiClient.get(`/ratings/${mediaType}/${tmdbId}`); export const saveRating=payload=>appApiClient.post('/ratings',payload); export const deleteRating=(mediaType,tmdbId)=>appApiClient.delete(`/ratings/${mediaType}/${tmdbId}`);
export const getReviews=(mediaType,tmdbId)=>appApiClient.get(`/reviews/${mediaType}/${tmdbId}`); export const saveReview=payload=>appApiClient.post('/reviews',payload); export const updateReview=(id,content)=>appApiClient.put(`/reviews/${id}`,{content}); export const deleteReview=id=>appApiClient.delete(`/reviews/${id}`);
export const getProfileStats=()=>appApiClient.get('/profile/stats'); export const getPersonalizedRecommendations=()=>appApiClient.get('/recommendations');
